     4	export interface JWTPayload {
     5	  id: string;
     6	  email: string;
     7	  role: string;
     8	  exp: number;
     9	  supportAccess?: boolean;
    10	}
    11	
    12	const JWT_SECRET = process.env.JWT_SECRET || "secret";
    13	
    14	export function hashMD5(text: string): string {
    15	  return crypto.createHash("md5").update(text).digest("hex");
    16	}
    17	
    18	function signHS256(data: string, secret: string): string {
    19	  return crypto.createHmac("sha256", secret).update(data).digest("base64url");
    20	}
    21	
    22	export function createSessionToken(payload: object): string {
    23	  const header = Buffer.from(
    24	    JSON.stringify({ alg: "HS256", typ: "JWT" })
    25	  ).toString("base64url");
    26	  const body = Buffer.from(JSON.stringify(payload)).toString("base64url");
    27	  const signature = signHS256(`${header}.${body}`, JWT_SECRET);
    28	  return `${header}.${body}.${signature}`;
    29	}
    30	
    31	export function decodeSessionToken(token: string): JWTPayload | null {
    32	  try {
    33	    const parts = token.split(".");
    34	    if (parts.length !== 3) {
    35	      return null;
    36	    }
    37	
    38	    const [header, body, signature] = parts;
    39	    const expectedSignature = signHS256(`${header}.${body}`, JWT_SECRET);
    40	
    41	    if (signature !== expectedSignature) {
    42	      return null;
    43	    }
    44	
    45	    const payload = JSON.parse(
    46	      Buffer.from(body, "base64url").toString("utf-8")
    47	    ) as JWTPayload;
    48	
    49	    if (payload.exp && payload.exp < Math.floor(Date.now() / 1000)) {
    50	      return null;
    51	    }
    52	
    53	    return payload;
    54	  } catch {
    55	    return null;
    56	  }
    57	}
    58	
    59	export async function getAuthenticatedUser(
    60	  request: NextRequest
    61	): Promise<JWTPayload | null> {
    62	  const token = request.cookies.get("authToken")?.value;
    63	
    64	  if (!token) {
    65	    return null;
    66	  }
    67	
    68	  return decodeSessionToken(token);
    69	}
    70	
    71	export function setAuthCookie(response: NextResponse, token: string): void {
    72	  response.cookies.set("authToken", token, {
    73	    httpOnly: true,
    74	    secure: process.env.NODE_ENV === "production",
    75	    sameSite: "lax",
    76	    maxAge: 60 * 60 * 24 * 7,
    77	    path: "/",
    78	  });
    79	}
    80	
    81	export function clearAuthCookie(response: NextResponse): void {
    82	  response.cookies.set("authToken", "", {
    83	    httpOnly: true,
    84	    secure: process.env.NODE_ENV === "production",
    85	    sameSite: "lax",
    86	    maxAge: 0,
    87	    path: "/",
    88	  });
    89	}
    90	
    91	// eslint-disable-next-line @typescript-eslint/no-explicit-any
    92	type RouteContext = { params: Promise<any> };
    93	
    94	type AuthenticatedHandler = (
    95	  request: NextRequest,
    96	  context: RouteContext,
    97	  user: JWTPayload
    98	) => Promise<NextResponse>;
    99	
   100	export function withAuth(handler: AuthenticatedHandler) {
   101	  return async (
   102	    request: NextRequest,
   103	    context: RouteContext
   104	  ): Promise<NextResponse> => {
   105	    const user = await getAuthenticatedUser(request);
   106	    if (!user) {
   107	      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
   108	    }
   109	    return handler(request, context, user);
   110	  };
   111	}
   112	
   113	export function withAdminAuth(handler: AuthenticatedHandler) {
   114	  return withAuth(async (request, context, user) => {
   115	    if (user.role !== "ADMIN") {
   116	      return NextResponse.json({ error: "Forbidden" }, { status: 403 });
   117	    }
   118	    return handler(request, context, user);
   119	  });
   120	}
