     1	import { getBaseUrl } from "./config";
     2	
     3	type RequestMethod = "GET" | "POST" | "PATCH" | "DELETE" | "PUT";
     4	
     5	interface RequestOptions {
     6	  method?: RequestMethod;
     7	  body?: unknown;
     8	  headers?: Record<string, string>;
     9	  cache?: RequestCache;
    10	}
    11	
    12	class ApiError extends Error {
    13	  status: number;
    14	  data?: unknown;
    15	
    16	  constructor(message: string, status: number, data?: unknown) {
    17	    super(message);
    18	    this.name = "ApiError";
    19	    this.status = status;
    20	    this.data = data;
    21	  }
    22	}
    23	
    24	async function apiRequest<T>(
    25	  endpoint: string,
    26	  options: RequestOptions = {}
    27	): Promise<T> {
    28	  const { method = "GET", body, headers = {}, cache } = options;
    29	
    30	  const baseUrl = getBaseUrl();
    31	  const url = `${baseUrl}${endpoint.startsWith("/") ? endpoint : `/${endpoint}`}`;
    32	
    33	  const requestHeaders: HeadersInit = {
    34	    "Content-Type": "application/json",
    35	    ...headers,
    36	  };
    37	
    38	  const fetchOptions: RequestInit = {
    39	    method,
    40	    headers: requestHeaders,
    41	    credentials: "include",
    42	  };
    43	
    44	  if (body) {
    45	    fetchOptions.body = JSON.stringify(body);
    46	  }
    47	
    48	  if (cache !== undefined) {
    49	    fetchOptions.cache = cache;
    50	  }
    51	
    52	  const response = await fetch(url, fetchOptions);
    53	
    54	  let data: unknown;
    55	  const contentType = response.headers.get("content-type");
    56	  if (contentType?.includes("application/json")) {
    57	    data = await response.json();
    58	  } else {
    59	    data = await response.text();
    60	  }
    61	
    62	  if (!response.ok) {
    63	    const errorMessage =
    64	      typeof data === "object" && data !== null && "error" in data
    65	        ? String(data.error)
    66	        : `Request failed with status ${response.status}`;
    67	
    68	    throw new ApiError(errorMessage, response.status, data);
    69	  }
    70	
    71	  return data as T;
    72	}
    73	
    74	export const api = {
    75	  get: <T>(
    76	    endpoint: string,
    77	    options?: Omit<RequestOptions, "method" | "body">
    78	  ) => apiRequest<T>(endpoint, { ...options, method: "GET" }),
    79	
    80	  post: <T>(
    81	    endpoint: string,
    82	    body?: unknown,
    83	    options?: Omit<RequestOptions, "method">
    84	  ) => apiRequest<T>(endpoint, { ...options, method: "POST", body }),
    85	
    86	  patch: <T>(
    87	    endpoint: string,
    88	    body?: unknown,
    89	    options?: Omit<RequestOptions, "method">
    90	  ) => apiRequest<T>(endpoint, { ...options, method: "PATCH", body }),
    91	
    92	  put: <T>(
    93	    endpoint: string,
    94	    body?: unknown,
    95	    options?: Omit<RequestOptions, "method">
    96	  ) => apiRequest<T>(endpoint, { ...options, method: "PUT", body }),
    97	
    98	  delete: <T>(
    99	    endpoint: string,
   100	    options?: Omit<RequestOptions, "method" | "body">
   101	  ) => apiRequest<T>(endpoint, { ...options, method: "DELETE" }),
