   109	          r."createdAt",
   110	          p.name as "productName"
   111	        FROM reviews r
   112	        INNER JOIN products p ON r."productId" = p.id
   113	        WHERE r.author = '${authorFilter}'
   114	        ORDER BY r."createdAt" DESC
   115	      `;
   117	        let queryResults: Record<string, unknown>[] = [];
   118	        const db = new Database(getDbPath());
   119	        try {
   120	          db.exec(query);
   121	          try {
   122	            queryResults = db
   123	              .prepare(
   124	                `SELECT
   125	                r.id,
   126	                r."productId",
   127	                r.content,
   128	                r.author,
   129	                r."createdAt",
   130	                p.name as "productName"
   131	              FROM reviews r
   132	              INNER JOIN products p ON r."productId" = p.id
   133	              WHERE r.author = '${authorFilter}'
   134	              ORDER BY r."createdAt" DESC`
   135	              )
   136	              .all() as Record<string, unknown>[];
   137	          } catch {
   138	            queryResults = [];
   139	          }
   140	        } catch {
   141	          queryResults = [];
   142	        } finally {
